package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func commonElements(a []int, b []int) []int {
	inA := make(map[int]bool)
	for _, x := range a {
		inA[x] = true
	}
	var common []int
	for _, x := range b {
		if inA[x] {
			common = append(common, x)
			delete(inA, x)
		}
	}
	sort.Ints(common)
	return common
}

func readNumbers(scanner *bufio.Scanner) []int {
	scanner.Scan()
	var numbers []int
